#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/pem.h>
#include <openssl/hmac.h>
#include <openssl/bio.h>
#include <openssl/buffer.h>
#include "db_driver.h"

#define MAX_TOKEN_LEN 4096
#define MAX_KEY_LEN 8192

typedef struct {
    char *header;
    char *payload;
    char *signature;
    int alg_type;  /* 0=HS256, 1=RS256, 2=ES256 */
} jwt_parts_t;

typedef struct {
    char *issuer;
    char *subject;
    long exp;
    int db_role;  /* 0=readonly, 1=readwrite, 2=admin */
} jwt_claims_t;

static const char *k8s_public_key_path = "/var/run/secrets/kubernetes.io/serviceaccount/ca.crt";
static const char *hmac_secret_path = "/etc/db-driver/hmac-secret";

static int base64url_decode(const char *input, unsigned char **output, int *out_len) {
    BIO *bio, *b64;
    int len = strlen(input);
    int padding = (4 - len % 4) % 4;
    char *padded = malloc(len + padding + 1);
    if (!padded) return -1;
    memcpy(padded, input, len);
    for (int i = 0; i < padding; i++) padded[len + i] = '=';
    padded[len + padding] = '\0';
    /* Convert base64url to base64 */
    for (int i = 0; i < len + padding; i++) {
        if (padded[i] == '-') padded[i] = '+';
        else if (padded[i] == '_') padded[i] = '/';
    }
    /* Reserve one extra byte so callers may safely NUL-terminate the output. */
    *output = malloc(len + padding + 1);
    if (!*output) { free(padded); return -1; }
    bio = BIO_new_mem_buf(padded, len + padding);
    b64 = BIO_new(BIO_f_base64());
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    bio = BIO_push(b64, bio);
    *out_len = BIO_read(bio, *output, len + padding);
    BIO_free_all(bio);
    free(padded);
    if (*out_len <= 0) { free(*output); *output = NULL; return -1; }
    return 0;
}

static int parse_alg_from_header(const char *header_json) {
    /* Minimal JSON parser for {"alg":"...","typ":"JWT"} */
    const char *alg_start = strstr(header_json, "\"alg\"");
    if (!alg_start) return -1;
    const char *colon = strchr(alg_start, ':');
    if (!colon) return -1;
    const char *quote1 = strchr(colon, '"');
    if (!quote1) return -1;
    quote1++;
    const char *quote2 = strchr(quote1, '"');
    if (!quote2) return -1;
    int alg_len = quote2 - quote1;
    if (alg_len == 5 && strncmp(quote1, "HS256", 5) == 0) return 0;
    if (alg_len == 5 && strncmp(quote1, "RS256", 5) == 0) return 1;
    if (alg_len == 5 && strncmp(quote1, "ES256", 5) == 0) return 2;
    return -1;
}

static int verify_signature_hmac(const char *signing_input, const char *sig_b64,
                                  const unsigned char *key, int key_len) {
    unsigned char *sig_bytes = NULL;
    int sig_len = 0;
    if (base64url_decode(sig_b64, &sig_bytes, &sig_len) != 0) return -1;
    unsigned char computed[EVP_MAX_MD_SIZE];
    unsigned int computed_len = 0;
    HMAC(EVP_sha256(), key, key_len, (unsigned char*)signing_input,
         strlen(signing_input), computed, &computed_len);
    int result = (sig_len == (int)computed_len &&
                  CRYPTO_memcmp(sig_bytes, computed, computed_len) == 0) ? 0 : -1;
    free(sig_bytes);
    return result;
}

static int verify_signature_rsa(const char *signing_input, const char *sig_b64,
                                 EVP_PKEY *pubkey) {
    unsigned char *sig_bytes = NULL;
    int sig_len = 0;
    if (base64url_decode(sig_b64, &sig_bytes, &sig_len) != 0) return -1;
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    if (!ctx) { free(sig_bytes); return -1; }
    if (EVP_DigestVerifyInit(ctx, NULL, EVP_sha256(), NULL, pubkey) != 1) {
        EVP_MD_CTX_free(ctx);
        free(sig_bytes);
        return -1;
    }
    if (EVP_DigestVerifyUpdate(ctx, signing_input, strlen(signing_input)) != 1) {
        EVP_MD_CTX_free(ctx);
        free(sig_bytes);
        return -1;
    }
    int result = EVP_DigestVerifyFinal(ctx, sig_bytes, sig_len) == 1 ? 0 : -1;
    EVP_MD_CTX_free(ctx);
    free(sig_bytes);
    return result;
}

/*
 * resolve_verification_key: Determines which key material to use based on
 * the configured trust model. In K8s deployments, RS256 tokens use the
 * service account CA cert; HS256 tokens use the mounted HMAC secret.
 *
 * The alg_type parameter indicates what the TOKEN claims; the
 * expected_alg parameter indicates what the CONFIGURATION expects.
 * Security invariant: we verify using the CONFIGURED algorithm's key.
 */
static int resolve_verification_key(int alg_type, int expected_alg,
                                     unsigned char **key_out, int *key_len_out,
                                     EVP_PKEY **pkey_out) {
    *pkey_out = NULL;
    *key_out = NULL;
    *key_len_out = 0;
    /*
     * Use expected_alg to select key material. This ensures an attacker
     * cannot force HMAC verification by changing the token header.
     */
    if (expected_alg == 0) {
        /* HMAC key from mounted secret */
        FILE *f = fopen(hmac_secret_path, "rb");
        if (!f) return -1;
        *key_out = malloc(MAX_KEY_LEN);
        if (!*key_out) { fclose(f); return -1; }
        *key_len_out = fread(*key_out, 1, MAX_KEY_LEN, f);
        fclose(f);
        return (*key_len_out > 0) ? 0 : -1;
    } else if (expected_alg == 1 || expected_alg == 2) {
        /* RSA/EC public key from K8s service account */
        FILE *f = fopen(k8s_public_key_path, "rb");
        if (!f) return -1;
        *pkey_out = PEM_read_PUBKEY(f, NULL, NULL, NULL);
        fclose(f);
        return (*pkey_out != NULL) ? 0 : -1;
    }
    return -1;
}

int db_authenticate_token(const char *token, jwt_claims_t *claims_out, int expected_alg) {
    if (!token || strlen(token) > MAX_TOKEN_LEN) return -1;
    /* Split token into parts */
    char *token_copy = strdup(token);
    if (!token_copy) return -1;
    char *dot1 = strchr(token_copy, '.');
    if (!dot1) { free(token_copy); return -1; }
    *dot1 = '\0';
    char *dot2 = strchr(dot1 + 1, '.');
    if (!dot2) { free(token_copy); return -1; }
    *dot2 = '\0';
    /* Decode header */
    unsigned char *header_bytes = NULL;
    int header_len = 0;
    if (base64url_decode(token_copy, &header_bytes, &header_len) != 0) {
        free(token_copy); return -1;
    }
    header_bytes[header_len] = '\0';
    int token_alg = parse_alg_from_header((char*)header_bytes);
    free(header_bytes);
    if (token_alg < 0) { free(token_copy); return -1; }
    /* Reject algorithm mismatch - prevent algorithm confusion */
    if (token_alg != expected_alg) { free(token_copy); return -1; }
    /* Resolve key material */
    unsigned char *hmac_key = NULL;
    int hmac_key_len = 0;
    EVP_PKEY *pubkey = NULL;
    if (resolve_verification_key(token_alg, expected_alg, &hmac_key, &hmac_key_len, &pubkey) != 0) {
        free(token_copy); return -1;
    }
    /* Reconstruct signing input */
    int si_len = (dot1 - token_copy) + 1 + (dot2 - dot1 - 1);
    char *signing_input = malloc(si_len + 1);
    if (!signing_input) { free(token_copy); free(hmac_key); EVP_PKEY_free(pubkey); return -1; }
    memcpy(signing_input, token_copy, dot1 - token_copy);
    signing_input[dot1 - token_copy] = '.';
    memcpy(signing_input + (dot1 - token_copy) + 1, dot1 + 1, dot2 - dot1 - 1);
    signing_input[si_len] = '\0';
    /* Verify based on expected algorithm */
    int verified = -1;
    if (expected_alg == 0) {
        verified = verify_signature_hmac(signing_input, dot2 + 1, hmac_key, hmac_key_len);
    } else if (expected_alg == 1) {
        verified = verify_signature_rsa(signing_input, dot2 + 1, pubkey);
    }
    free(signing_input);
    free(hmac_key);
    EVP_PKEY_free(pubkey);
    free(token_copy);
    if (verified != 0) return -1;
    /* Parse claims (simplified) */
    claims_out->db_role = 2; /* placeholder - real impl parses payload */
    return 0;
}

/* Entry point for K8s sidecar authentication */
int db_driver_init(const char *connection_string, const char *auth_token) {
    jwt_claims_t claims;
    memset(&claims, 0, sizeof(claims));
    /* K8s deployment expects RS256 tokens from the API server */
    int expected_alg = 1; /* RS256 */
    if (db_authenticate_token(auth_token, &claims, expected_alg) != 0) {
        fprintf(stderr, "db_driver: authentication failed\n");
        return -1;
    }
    if (claims.db_role < 0 || claims.db_role > 2) return -1;
    /* Proceed with authenticated connection */
    return establish_db_connection(connection_string, claims.db_role);
}
